import React, { useState, useEffect, useMemo } from 'react';
import { 
  XAxis, YAxis, Tooltip, ResponsiveContainer, BarChart, Bar, Cell, AreaChart, Area, ComposedChart 
} from 'recharts';
import { 
  Calendar, 
  Heart, 
  Plus, 
  ChevronLeft, 
  ChevronRight, 
  BarChart2, 
  Activity, 
  Zap, 
  User, 
  Flame, 
  Pill, 
  Droplets,
  CheckCircle2,
  TrendingUp,
  History
} from 'lucide-react';

const LIBIDO_LEVELS = {
  1: { label: "Zero", color: "#7c3aed" },
  2: { label: "Baixa", color: "#a855f7" },
  3: { label: "Média", color: "#d946ef" },
  4: { label: "Alta", color: "#ec4899" },
  5: { label: "Pico", color: "#f43f5e" }
};

const App = () => {
  const [records, setRecords] = useState([]);
  const [view, setView] = useState('dashboard');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [feedback, setFeedback] = useState(null);

  // Inicialização e Persistência
  useEffect(() => {
    const saved = localStorage.getItem('conexao_v7_data');
    if (saved) {
      setRecords(JSON.parse(saved));
    } else {
      // Dados baseados no seu relato histórico
      const initialData = [
        { id: '1', date: '2026-01-10', hadSex: true, libido: 4, masturbated: false },
        { id: '2', date: '2026-01-18', hadSex: true, libido: 3, masturbated: false, usedTadala: true },
        { id: '3', date: '2026-01-24', hadSex: true, libido: 4, masturbated: false },
        { id: '4', date: '2026-02-01', hadSex: true, libido: 5, masturbated: false },
        { id: '5', date: '2026-02-04', hadSex: true, libido: 5, masturbated: true },
        { id: 'm1', date: '2026-02-05', hadSex: false, libido: 4, masturbated: true },
        { id: 'm2', date: '2026-02-06', hadSex: false, libido: 5, masturbated: true },
      ];
      setRecords(initialData);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('conexao_v7_data', JSON.stringify(records));
  }, [records]);

  // Função de Registro Rápido
  const quickLog = (type) => {
    const today = new Date().toISOString().split('T')[0];
    const existingIndex = records.findIndex(r => r.date === today);

    let updatedRecords = [...records];
    let message = "";

    if (existingIndex > -1) {
      const record = updatedRecords[existingIndex];
      if (type === 'sex') { record.hadSex = true; record.libido = 5; message = "Transa registrada!"; }
      if (type === 'solo') { record.masturbated = true; record.libido = Math.max(record.libido, 4); message = "Masturbação registrada!"; }
      if (type === 'tadala') { record.usedTadala = true; message = "Uso de Tadala registrado!"; }
      if (type === 'period_end') { record.periodEnded = true; message = "Fim de ciclo registrado!"; }
    } else {
      const newRecord = {
        id: Date.now().toString(),
        date: today,
        hadSex: type === 'sex',
        masturbated: type === 'solo',
        usedTadala: type === 'tadala',
        periodEnded: type === 'period_end',
        libido: type === 'sex' || type === 'solo' ? 4 : 3
      };
      updatedRecords.push(newRecord);
      message = "Novo registro criado para hoje!";
    }

    setRecords(updatedRecords);
    setFeedback(message);
    setTimeout(() => setFeedback(null), 3000);
  };

  const stats = useMemo(() => {
    const currentYear = new Date().getFullYear();
    const annualTotal = records.filter(r => r.hadSex && r.date.startsWith(currentYear.toString())).length;

    // Dados para o gráfico da semana
    const last7Days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      const r = records.find(rec => rec.date === dateStr);
      last7Days.push({
        day: d.getDate(),
        libido: r ? r.libido : 0,
        activity: r && (r.hadSex || r.masturbated) ? 1 : 0
      });
    }

    return { annualTotal, last7Days };
  }, [records]);

  const renderDashboard = () => (
    <div className="space-y-6 pb-28">
      {/* Feedback Toast */}
      {feedback && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-50 bg-gray-900 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-2 animate-in fade-in slide-in-from-top-4">
          <CheckCircle2 size={18} className="text-green-400" />
          <span className="text-sm font-bold">{feedback}</span>
        </div>
      )}

      {/* Registro Rápido - OS BOTÕES QUE VOCÊ PEDIU */}
      <section className="bg-white p-6 rounded-[32px] shadow-sm border border-pink-50">
        <h4 className="font-black text-gray-400 uppercase text-[10px] tracking-widest mb-4">Registro Rápido (Hoje)</h4>
        <div className="grid grid-cols-2 gap-3">
          <button 
            onClick={() => quickLog('sex')}
            className="flex flex-col items-center justify-center p-4 rounded-2xl bg-pink-500 text-white shadow-lg shadow-pink-100 active:scale-95 transition-all"
          >
            <Heart size={24} fill="currentColor" />
            <span className="text-[10px] font-black uppercase mt-2">Transamos</span>
          </button>
          <button 
            onClick={() => quickLog('solo')}
            className="flex flex-col items-center justify-center p-4 rounded-2xl bg-purple-600 text-white shadow-lg shadow-purple-100 active:scale-95 transition-all"
          >
            <User size={24} />
            <span className="text-[10px] font-black uppercase mt-2">Masturbação</span>
          </button>
          <button 
            onClick={() => quickLog('tadala')}
            className="flex flex-col items-center justify-center p-4 rounded-2xl bg-indigo-50 text-indigo-600 border border-indigo-100 active:scale-95 transition-all"
          >
            <Pill size={20} />
            <span className="text-[10px] font-black uppercase mt-2">Usei Tadala</span>
          </button>
          <button 
            onClick={() => quickLog('period_end')}
            className="flex flex-col items-center justify-center p-4 rounded-2xl bg-red-50 text-red-600 border border-red-100 active:scale-95 transition-all"
          >
            <Droplets size={20} />
            <span className="text-[10px] font-black uppercase mt-2">Fim Ciclo Dela</span>
          </button>
        </div>
      </section>

      {/* Resumo Anual */}
      <div className="bg-gray-900 p-6 rounded-[32px] text-white shadow-xl">
        <div className="flex justify-between items-center mb-2">
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-500">Performance Anual</p>
          <TrendingUp size={14} className="text-pink-500" />
        </div>
        <div className="flex items-baseline gap-2">
          <h2 className="text-5xl font-black">{stats.annualTotal}</h2>
          <p className="text-gray-400 font-bold uppercase text-xs">Vezes no Ano</p>
        </div>
        <div className="mt-4 bg-gray-800 h-2 rounded-full overflow-hidden">
          <div className="bg-pink-500 h-full transition-all duration-500" style={{ width: `${(stats.annualTotal / 20) * 100}%` }}></div>
        </div>
      </div>

      {/* Gráfico de Libido Semanal */}
      <div className="bg-white p-6 rounded-[32px] shadow-sm">
        <div className="flex justify-between items-center mb-6">
           <h4 className="font-black text-gray-400 uppercase text-[10px] tracking-widest">Onda de Desejo (7 dias)</h4>
           <Flame size={18} className="text-orange-500 animate-pulse" />
        </div>
        <div className="h-40 w-full">
           <ResponsiveContainer width="100%" height="100%">
             <AreaChart data={stats.last7Days}>
               <defs>
                 <linearGradient id="colorLibido" x1="0" y1="0" x2="0" y2="1">
                   <stop offset="5%" stopColor="#ec4899" stopOpacity={0.3}/>
                   <stop offset="95%" stopColor="#ec4899" stopOpacity={0}/>
                 </linearGradient>
               </defs>
               <Tooltip 
                contentStyle={{ borderRadius: '16px', border: 'none', fontWeight: 'bold' }}
                cursor={{ stroke: '#ec4899', strokeWidth: 2 }}
               />
               <Area type="monotone" dataKey="libido" stroke="#ec4899" strokeWidth={4} fillOpacity={1} fill="url(#colorLibido)" />
             </AreaChart>
           </ResponsiveContainer>
        </div>
      </div>

      {/* Histórico Recente */}
      <div className="space-y-3">
        <div className="flex items-center gap-2 px-1">
          <History size={14} className="text-gray-400" />
          <h4 className="font-black text-gray-400 uppercase text-[10px] tracking-widest">Atividades Recentes</h4>
        </div>
        {[...records].reverse().slice(0, 4).map(r => (
          <div key={r.id} className="bg-white p-4 rounded-2xl flex items-center justify-between shadow-sm border border-gray-50">
            <div className="flex items-center gap-3">
               <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${r.hadSex ? 'bg-pink-500 text-white' : 'bg-gray-100 text-gray-400'}`}>
                  {r.hadSex ? <Heart size={18} fill="currentColor" /> : (r.masturbated ? <User size={18} /> : <Zap size={18} />)}
               </div>
               <div>
                  <p className="font-bold text-sm">{new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR', {day: '2-digit', month: 'short'})}</p>
                  <p className="text-[9px] font-black text-gray-400 uppercase">Libido {LIBIDO_LEVELS[r.libido]?.label || 'Média'}</p>
               </div>
            </div>
            <div className="flex gap-1">
              {r.usedTadala && <div className="p-1 bg-indigo-50 text-indigo-600 rounded-lg"><Pill size={12} /></div>}
              {r.periodEnded && <div className="p-1 bg-red-50 text-red-600 rounded-lg"><Droplets size={12} /></div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const renderCalendar = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const days = [...Array(getDaysInMonth(year, month)).keys()].map(i => i + 1);
    const firstDay = new Date(year, month, 1).getDay();
    const calendarDays = [...Array(firstDay).fill(null), ...days];

    return (
      <div className="bg-white p-6 rounded-[32px] shadow-sm">
        <div className="flex items-center justify-between mb-8">
          <button onClick={() => setCurrentDate(new Date(year, month - 1, 1))} className="p-2"><ChevronLeft size={20}/></button>
          <h3 className="font-black text-lg text-gray-800 uppercase">{getMonthName(month)} {year}</h3>
          <button onClick={() => setCurrentDate(new Date(year, month + 1, 1))} className="p-2"><ChevronRight size={20}/></button>
        </div>
        <div className="grid grid-cols-7 gap-2 text-center mb-4 text-gray-300 text-[10px] font-black uppercase">
          {['D', 'S', 'T', 'Q', 'Q', 'S', 'S'].map(d => <span key={d}>{d}</span>)}
        </div>
        <div className="grid grid-cols-7 gap-2">
          {calendarDays.map((day, idx) => {
            if (!day) return <div key={idx} />;
            const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
            const r = records.find(rec => rec.date === dateStr);
            const hasActivity = r && (r.hadSex || r.masturbated);

            return (
              <div key={idx} className={`aspect-square flex flex-col items-center justify-center rounded-2xl relative text-xs
                ${r?.hadSex ? 'bg-pink-500 text-white font-black shadow-lg shadow-pink-100' : (r?.masturbated ? 'bg-purple-100 text-purple-600 font-bold' : 'text-gray-400 hover:bg-gray-50')}
              `}>
                {day}
                {r?.usedTadala && <div className="absolute top-1 right-1 w-1 h-1 bg-indigo-400 rounded-full" />}
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans text-gray-900 flex justify-center">
      <div className="w-full max-w-md bg-gray-50 min-h-screen relative shadow-2xl flex flex-col">
        {/* Header */}
        <header className="p-6 flex justify-between items-center bg-white/80 backdrop-blur-md border-b sticky top-0 z-40">
          <div>
            <h1 className="text-xl font-black text-gray-800 tracking-tighter">CONEXÃO</h1>
            <p className="text-[10px] text-pink-500 font-bold uppercase tracking-widest leading-none">Gestão de Performance</p>
          </div>
          <button className="w-10 h-10 bg-gray-50 rounded-2xl flex items-center justify-center text-gray-400"><Activity size={18} /></button>
        </header>

        {/* Content Area */}
        <main className="flex-1 p-6 overflow-y-auto">
          {view === 'dashboard' ? renderDashboard() : renderCalendar()}
        </main>

        {/* Navigation */}
        <nav className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[90%] max-w-[360px] bg-white/90 backdrop-blur-xl border border-white rounded-[32px] shadow-2xl flex justify-around py-3 z-30">
          <button onClick={() => setView('dashboard')} className={`p-2 rounded-2xl transition-all ${view === 'dashboard' ? 'text-pink-500 bg-pink-50 shadow-inner' : 'text-gray-400'}`}>
            <BarChart2 size={24} />
          </button>
          <button onClick={() => setView('calendar')} className={`p-2 rounded-2xl transition-all ${view === 'calendar' ? 'text-pink-500 bg-pink-50 shadow-inner' : 'text-gray-400'}`}>
            <Calendar size={24} />
          </button>
        </nav>
      </div>
    </div>
  );
};

export default App;

