             // Se tem registro: Cor da borda/fundo baseada na Libido? Ou no ato?
             // Vamos priorizar o ATO (Sexo > Solo > Nada)
             let bgClass = "bg-gray-50 border-2 border-transparent text-gray-300"; // Default: Vazio

             if (record) {
                if (record.hadSex) bgClass = "bg-pink-500 text-white shadow-lg shadow-pink-200 border-2 border-pink-500";
                else if (record.masturbated) bgClass = "bg-purple-100 text-purple-600 border-2 border-purple-200";
                else bgClass = "bg-white border-2 border-green-200 text-green-700"; // Check-in feito, nada rolou
             } else if (isToday) {
               bgClass = "bg-gray-900 text-white border-2 border-gray-900"; // Hoje sem registro
             }

             return (
               <div key={day} className={`aspect-square rounded-2xl flex flex-col items-center justify-center relative ${bgClass}`}>
                  <span className="font-bold text-sm z-10">{day}</span>
                  {/* Marcadores de Tadala/Ciclo */}
                  <div className="flex gap-1 absolute bottom-1">
                    {record?.usedTadala && <div className="w-1.5 h-1.5 rounded-full bg-blue-400 ring-1 ring-white"></div>}
                    {record?.periodEnded && <div className="w-1.5 h-1.5 rounded-full bg-red-400 ring-1 ring-white"></div>}
                  </div>
               </div>
             )
          })}
        </div>

        <div className="mt-8 flex flex-col gap-2 text-xs font-bold text-gray-400">
           <div className="flex items-center gap-2"><div className="w-4 h-4 bg-pink-500 rounded-md"></div> Transamos</div>
           <div className="flex items-center gap-2"><div className="w-4 h-4 bg-purple-100 border-2 border-purple-200 rounded-md"></div> Solo</div>
           <div className="flex items-center gap-2"><div className="w-4 h-4 bg-white border-2 border-green-200 rounded-md"></div> Check-in (Nada rolou)</div>
           <div className="flex items-center gap-2"><div className="w-4 h-4 bg-gray-50 rounded-md"></div> Sem registro</div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FDFBF7] font-sans text-slate-900 flex justify-center selection:bg-pink-200">
      <div className="w-full max-w-md bg-[#FDFBF7] min-h-screen relative shadow-2xl flex flex-col">

        {/* Header Minimalista */}
        <header className="p-6 flex justify-between items-center bg-[#FDFBF7]/90 backdrop-blur-sm sticky top-0 z-30">
          <div>
             <h1 className="text-3xl font-black tracking-tight text-gray-800">Conexão<span className="text-pink-500">.</span></h1>
          </div>
          <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center shadow-sm border border-gray-100">
             <User size={20} className="text-gray-400" />
          </div>
        </header>

        {/* Conteúdo Principal */}
        <main className="flex-1 p-6 overflow-y-auto no-scrollbar">
          {view === 'dashboard' ? renderDashboard() : renderCalendar()}
        </main>

        {/* Menu Inferior Flutuante */}
        <nav className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[85%] max-w-[340px] bg-gray-900 text-white rounded-[32px] shadow-2xl shadow-gray-400/50 flex justify-around items-center py-4 z-40">
