             onClick={() => setView('dashboard')} 
             className={`p-2 transition-all duration-300 ${view === 'dashboard' ? 'text-pink-400 scale-125' : 'text-gray-500 hover:text-white'}`}
           >
             <BarChart2 size={28} strokeWidth={3} />
           </button>

           {/* Botão Central de Ação Rápida (Abre o modal se não estiver no calendário) */}
           <div className="w-px h-8 bg-gray-700"></div>

           <button 
             onClick={() => setView('calendar')} 
             className={`p-2 transition-all duration-300 ${view === 'calendar' ? 'text-pink-400 scale-125' : 'text-gray-500 hover:text-white'}`}
           >
             <Calendar size={28} strokeWidth={3} />
           </button>
        </nav>

        {/* Modal de Check-in */}
        {isCheckinOpen && renderCheckinModal()}

      </div>
    </div>
  );
};

