  hadSex: boolean;
  libido: number;
  masturbated: boolean;
  usedTadala: boolean;
  periodEnded: boolean;
  timestamp: number;
}

interface LibidoLevel {
  label: string;
  color: string;
  icon: React.ReactNode;
}

// --- Constants ---
const LIBIDO_LEVELS: { [key: number]: LibidoLevel } = {
  1: { label: "Zero", color: "#94a3b8", icon: <Frown size={32} /> },
  2: { label: "Baixa", color: "#a855f7", icon: <Meh size={32} /> },
  3: { label: "Média", color: "#d946ef", icon: <Smile size={32} /> },
  4: { label: "Alta", color: "#ec4899", icon: <Flame size={32} /> },
  5: { label: "Pico", color: "#f43f5e", icon: <Flame size={32} fill="currentColor" /> }
};

