        <main className="flex-1 p-6 overflow-y-auto no-scrollbar">
          {view === 'dashboard' ? renderDashboard() : renderCalendar()}
        </main>

        {/* Menu Inferior Flutuante */}
        <nav className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[85%] max-w-[340px] bg-gray-900 text-white rounded-[32px] shadow-2xl shadow-gray-400/50 flex justify-around items-center py-4 z-40">
