interface LibidoLevel {
  label: string;
  color: string;
  icon: React.ReactNode;
}

// --- Constants ---
// Red/Passion Theme Colors
const LIBIDO_LEVELS: { [key: number]: LibidoLevel } = {
  1: { label: "Zero", color: "#9ca3af", icon: <Frown size={32} /> }, // Gray
  2: { label: "Baixa", color: "#fca5a5", icon: <Meh size={32} /> }, // Light Red
  3: { label: "Média", color: "#ef4444", icon: <Smile size={32} /> }, // Red
