      .sort((a, b) => b.timestamp - a.timestamp)[0];

    if (!lastCycleEnd) return null;

    const lastCycleDate = new Date(lastCycleEnd.date + 'T12:00:00');
    const today = new Date();
    const diffTime = Math.abs(today.getTime() - lastCycleDate.getTime());
    const daysSinceEnd = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 

