    // Day 0: Period Ends
    // Day 1: 1 day without meds -> PEAK LIBIDO (Tarada)
    // Day 2: 2 days without meds -> HIGH LIBIDO
    // Day 3-21: Taking meds -> Normal/Variable
    // Day 22-28: Period/PMS -> Low

    let predictedLibido = 3;
    let statusText = "Normal";
    let statusColor = "text-gray-500";

    if (daysSinceEnd === 1) {
      predictedLibido = 5;
      statusText = "Fogo Alto (Sem remédio)";
