        {/* Conteúdo Principal */}
        <main className="flex-1 p-6 overflow-y-auto no-scrollbar">
          {renderDashboard()}
        </main>

        {/* Modal de Check-in */}
        {isCheckinOpen && renderCheckinModal()}

      </div>
    </div>
  );
};

