  Activity, 
  User, 
  Flame, 
  Pill, 
  Droplets,
  CheckCircle2,
  Plus,
  X as XIcon,
  Edit3,
  Smile,
  Frown,
  Meh,
  LogOut,
  Sparkles,
  Zap,
  CalendarHeart,
  Ban,
