          // She started meds after period
          statusText = "Estável (Com Med)";
          statusColor = "text-blue-500";
          predictedLibido = 3;
        } else if (tMedsEnd > tMedsStart && tMedsEnd > tEnd) {
          // She stopped meds recently (Pausa)
