  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  writeBatch 
} from 'firebase/firestore';

// --- Types ---
interface Record {
  id: string;
  date: string;
  hadSex: boolean;
  libido: number;
  masturbated: boolean;
  usedTadala: boolean;

  // Legacy support (will be treated as periodEnds)
  periodEnded: boolean; 

  // New Cycle Tracking
  periodStarts?: boolean; // Menstruação desceu
  periodEnds?: boolean;   // Menstruação acabou
  medsStarts?: boolean;   // Começou cartela
  medsEnds?: boolean;     // Parou cartela (Pausa)

  timestamp: number;
}

interface LibidoLevel {
  label: string;
  value: number;
  color: string;
  icon: React.ReactNode;
}

// --- Constants ---
// Red/Passion Theme Colors
const LIBIDO_LEVELS: { [key: number]: LibidoLevel } = {
  1: { label: "Zero", value: 1, color: "#9ca3af", icon: <Frown size={32} /> }, // Gray
  2: { label: "Baixa", value: 2, color: "#fca5a5", icon: <Meh size={32} /> }, // Light Red
  3: { label: "Média", value: 3, color: "#ef4444", icon: <Smile size={32} /> }, // Red
  4: { label: "Alta", value: 4, color: "#b91c1c", icon: <Flame size={32} /> }, // Dark Red
  5: { label: "Pico", value: 5, color: "#7f1d1d", icon: <Flame size={32} fill="currentColor" /> } // Deep Blood Red
};

// --- Components ---

// Simple Text Logo Component
const ConexaoTextLogo = ({ size = "large" }: { size?: "small" | "large" }) => (
  <div className={`font-black tracking-tighter italic select-none w-full text-center ${
    size === 'large' 
      ? 'text-5xl sm:text-7xl' 
      : 'text-2xl sm:text-3xl'
  }`}>
    <span className="bg-clip-text text-transparent bg-gradient-to-r from-[#7f1d1d] via-[#dc2626] to-[#fb923c] drop-shadow-sm px-2 py-1 inline-block">
      CONEXÃO
    </span>
  </div>
);

const App: React.FC = () => {
  // State
  const [hasEntered, setHasEntered] = useState(false);
  const [records, setRecords] = useState<Record[]>([]);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isCheckinOpen, setIsCheckinOpen] = useState(false);

  // Check-in Form State
  const [checkinLibido, setCheckinLibido] = useState<number>(3);

  // User Activities
  const [checkinActivities, setCheckinActivities] = useState({
    hadSex: false,
    masturbated: false,
    usedTadala: false
  });

  // Partner Activities (Marcelly)
  const [checkinPartner, setCheckinPartner] = useState({
    periodStarts: false,
    periodEnds: false, // Replaces periodEnded logic
    medsStarts: false,
    medsEnds: false
  });

  // Firebase Synchronization & Initial Seeding
  useEffect(() => {
    // Reference to the collection
    const recordsCollection = collection(db, "conexao_records");

    // Real-time listener
    const unsubscribe = onSnapshot(recordsCollection, async (snapshot) => {
      if (snapshot.empty) {
        // --- SEED INITIAL DATA IF DB IS EMPTY ---
        console.log("Database empty. Seeding initial data...");
        const currentYear = new Date().getFullYear();
        const todayStr = new Date().toISOString().split('T')[0];
        const batch = writeBatch(db);

        // Create the "Today" record requested by user
        // Using date as ID to avoid duplicates on re-runs
        const todayRequest: Record = { 
          id: todayStr, 
          date: todayStr, 
          hadSex: true, 
          libido: 5, // Tesão muito alto
          masturbated: true, // Punheta
          usedTadala: false, 
          periodEnded: false, 
          timestamp: Date.now() 
        };

        const initialData: Record[] = [
          { id: `${currentYear}-01-10`, date: `${currentYear}-01-10`, hadSex: true, libido: 4, masturbated: false, usedTadala: false, periodEnded: false, timestamp: Date.parse(`${currentYear}-01-10`) },
          { id: `${currentYear}-01-18`, date: `${currentYear}-01-18`, hadSex: true, libido: 3, masturbated: false, usedTadala: true, periodEnded: false, timestamp: Date.parse(`${currentYear}-01-18`) },
          { id: `${currentYear}-01-24`, date: `${currentYear}-01-24`, hadSex: true, libido: 5, masturbated: false, usedTadala: false, periodEnded: false, timestamp: Date.parse(`${currentYear}-01-24`) },
          { id: `${currentYear}-02-01`, date: `${currentYear}-02-01`, hadSex: true, libido: 5, masturbated: false, usedTadala: false, periodEnded: false, timestamp: Date.parse(`${currentYear}-02-01`) },
          { id: `${currentYear}-02-04`, date: `${currentYear}-02-04`, hadSex: true, libido: 5, masturbated: true, usedTadala: false, periodEnded: true, timestamp: Date.parse(`${currentYear}-02-04`) },
          todayRequest
        ];

        initialData.forEach(record => {
           // Ensure ID is string
           const docRef = doc(recordsCollection, record.id);
           batch.set(docRef, record);
        });

        try {
          await batch.commit();
          console.log("Initial data seeded successfully.");
        } catch (error) {
          console.error("Error seeding data:", error);
        }
      } else {
        // --- LOAD DATA FROM FIRESTORE ---
        const loadedRecords = snapshot.docs.map(doc => doc.data() as Record);
        setRecords(loadedRecords);
      }
    });

    // Cleanup listener on unmount
    return () => unsubscribe();
  }, []);

  // Helpers
  const todayStr = new Date().toISOString().split('T')[0];
  const todayRecord = records.find(r => r.date === todayStr);

  const handleOpenCheckin = () => {
    if (todayRecord) {
      setCheckinLibido(todayRecord.libido);
      setCheckinActivities({
        hadSex: todayRecord.hadSex,
        masturbated: todayRecord.masturbated,
        usedTadala: todayRecord.usedTadala,
      });
      setCheckinPartner({
        periodStarts: todayRecord.periodStarts || false,
        periodEnds: todayRecord.periodEnds || todayRecord.periodEnded || false,
        medsStarts: todayRecord.medsStarts || false,
        medsEnds: todayRecord.medsEnds || false
      });
    } else {
      setCheckinLibido(3);
      setCheckinActivities({ hadSex: false, masturbated: false, usedTadala: false });
      setCheckinPartner({ periodStarts: false, periodEnds: false, medsStarts: false, medsEnds: false });
