    periodStarts: false,
    periodEnds: false, // Replaces periodEnded logic
    medsStarts: false,
    medsEnds: false
  });

  // Load Data with Fallback & Inject User Request
  useEffect(() => {
    const saved = localStorage.getItem('conexao_v7_data');
