           <h2 className="text-sm font-black text-gray-400 uppercase tracking-wider">HOJE</h2>
           <span className="text-sm font-bold text-red-500 capitalize">{new Date().toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric' })}</span>
