                <Sparkles size={18} />
                <span className="text-xs font-black uppercase tracking-widest">Sincronia</span>
              </div>
              <div className="text-right">
                <p className="text-[10px] font-bold text-red-300 uppercase tracking-widest">Ciclo Selene</p>
